import path from 'node:path';
import zlib from 'node:zlib';

function decompressMulti(buf) {
  const pos = [];
  for (let i = 0; i <= buf.length - 4; i++) {
    if (buf[i] === 0x28 && buf[i + 1] === 0xb5 && buf[i + 2] === 0x2f && buf[i + 3] === 0xfd) pos.push(i);
  }
  const outs = [];
  let i = 0;
  while (i < pos.length) {
    let ok = false;
    for (let j = i + 1; j <= pos.length; j++) {
      const end = j < pos.length ? pos[j] : buf.length;
      try {
        outs.push(zlib.zstdDecompressSync(buf.subarray(pos[i], end)));
        i = j; ok = true; break;
      } catch (e) { /* merge next frame */ }
    }
    if (!ok) { i++; }
  }
  return { data: Buffer.concat(outs), frames: pos.length };
}

const ROOT = './';
const dirs = fs.readdirSync(ROOT, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name);
console.log('sessionDirs', dirs.length);
const main = 'session-c8676d8b-8978-4215-a51d-764c891f05c8';
const f = path.join(ROOT, main, 'session.v4.jsonl.zstd');
const raw = fs.readFileSync(f);
const { data, frames } = decompressMulti(raw);
const text = data.toString('utf8');
const lines = text.split('\n').filter(l => l.trim());
console.log('fileBytes', raw.length, 'frames', frames, 'lines', lines.length);
const evs = [];
let bad = 0;
for (const l of lines) { try { evs.push(JSON.parse(l)); } catch (e) { bad++; } }
console.log('parsed', evs.length, 'bad', bad);
const counts = {};
for (const e of evs) counts[e.type] = (counts[e.type] || 0) + 1;
console.log('types', JSON.stringify(counts));
const seen = new Set();
for (const e of evs) {
  if (seen.has(e.type)) continue;
  seen.add(e.type);
  console.log('--- schema', e.type, JSON.stringify(Object.keys(e)));
  const s = JSON.stringify(e);
  console.log('    sample', s.slice(0, 300));
}
// time field detection
console.log('first ev time keys', JSON.stringify(Object.keys(evs[0])));
console.log('ev0', JSON.stringify(evs[0]).slice(0, 400));
console.log('evlast', JSON.stringify(evs[evs.length - 1]).slice(0, 300));
// sample user messages
let n = 0;
for (let i = 0; i < evs.length; i++) {
  const e = evs[i];
  if (e.type === 'user/message') {
    console.log('USER[' + i + '] keys', JSON.stringify(Object.keys(e)), 'msgKeys', e.message ? JSON.stringify(Object.keys(e.message)) : 'no-msg');
    const s = JSON.stringify(e).slice(0, 320);
    console.log('   ', s);
    if (++n >= 4) break;
  }
}
// subagent catalog
const cat = evs.find(e => e.type === 'subagent/catalog');
if (cat) console.log('CATALOG', JSON.stringify(cat).slice(0, 1200));
"}

