{"content":"import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const ROOT = './';
const OUT = './';
const MAIN = 'session-c8676d8b-8978-4215-a51d-764c891f05c8';
const CUTOFF = Date.parse('2026-11-26T12:00:00+08:00');
const KEEP = new Set(['user/message', 'assistant/message', 'tool/call', 'tool/result', 'turn/start', 'turn/end', 'subagent/catalog']);

function decompressMulti(buf) {
  const pos = [];
  for (let i = 0; i <= buf.length - 4; i++) {
    if (buf[i] === 0x28 && buf[i + 1] === 0xb5 && buf[i + 2] === 0x2f && buf[i + 3] === 0xfd) pos.push(i);
  }
  const outs = [];
  const fails = [];
  let i = 0;
  while (i < pos.length) {
    let ok = false;
    for (let j = i + 1; j <= pos.length; j++) {
      const end = j < pos.length ? pos[j] : buf.length;
      try { outs.push(zlib.zstdDecompressSync(buf.subarray(pos[i], end))); i = j; ok = true; break; } catch (e) { /* merge */ }
    }
    if (!ok) { fails.push(pos[i]); i++; }
  }
  return { data: Buffer.concat(outs), frames: pos.length, fails };
}

// ---------- desensitize ----------
function scrub(s) {
  if (typeof s !== 'string') return s;
  let t = s;
  t = t.replace(/fil./)"'`<>]*/g, './');
  t = t.replace(/[A-Za-z]:[\\/][^\s"'`<>|，。；、）)]*/g, './');
  t = t.replace(/[A-Za-z]:\\(?=\\|\s|$|["'`])/g, './');
  t = t.replace(/用户/g, '\u7528\u6237');
  t = t.replace(/\u8521\u767d\u83dc/g, '\u7528\u6237');
  t = t.replace(/UID\s*[:：]\s*\d+/g, '\u67d0\u7528\u6237');
  t = t.replace(/\u5927\u5b66|\u5b66\u9662|\u9ad8\u6821/g, '\u5b66\u6821');
  t = t.replace(/\u6211\u5e38\u901b/g, '\u6211\u5e38\u53bb');
  t = t.replace(/\u6211\u5173\u6ce8/g, '\u6211\u7559\u610f');
  t = t.replace(/api\s*key/gi, '\u51ed\u636e');
  t = t.replace(/token\s*=/gi, '\u51ed\u636e=');
  return t;
}
function scrubDeep(v) {
  if (typeof v === 'string') return scrub(v);
  if (Array.isArray(v)) return v.map(scrubDeep);
  if (v && typeof v === 'object') { const o = {}; for (const k of Object.keys(v)) o[k] = scrubDeep(v[k]); return o; }
  return v;
}

// ---------- helpers ----------
function trunc(s, max) {
  if (typeof s !== 'string') return '';
  if (s.length <= max) return s;
  return s.slice(0, max) + '\u2026\uff08\u622a\u65ad\uff0c\u539f\u6587 ' + s.length + ' \u5b57\u7b26\uff09';
}
function partsText(content) {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  const out = [];
  for (const p of content) {
    if (!p || typeof p !== 'object') continue;
    if (p.type === 'text' && typeof p.text === 'string') out.push(p.text);
    else if (p.type === 'image') out.push('[\u56fe\u7247]');
    else if (p.type === 'reasoning') continue;
  }
  return out.join('\n').trim();
}
function blockquote(s) {
  return s.split('\n').map(l => (l.length ? '> ' + l : '>')).join('\n');
}
function oneLine(s) {
  return String(s).replace(/\r?\n/g, ' \u23ce ').trim();
}
function argsSummary(raw) {
  if (typeof raw !== 'string') return '';
  let v = raw;
  try { v = JSON.parse(raw); } catch (e) { return trunc(oneLine(raw), 600); }
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    const parts = [];
    for (const k of Object.keys(v)) {
      let val = v[k];
      let s = typeof val === 'string' ? val : JSON.stringify(val);
      if (s === undefined) s = 'null';
      if (s.length > 180) s = s.slice(0, 180) + '\u2026';
      parts.push(k + '=' + s);
    }
    return trunc(oneLine(parts.join(' \u00b7 ')), 600);
  }
  return trunc(oneLine(String(v)), 600);
}
const SYS_RE = /^<system-reminder>|^<available_skills>|^<skill_content>/;
const MEM_RE = /^\u3014\u8bb0\u5fc6\u53ec\u56de/;

function renderUserText(t) {
  if (SYS_RE.test(t.trim())) return null;
  if (MEM_RE.test(t.trim())) {
    const m = t.match(/\uff08\u6b63\u6587\u7528 mem_get[^\n]*\n/);
    if (m) {
      const rest = t.slice(t.indexOf(m[0]) + m[0].length).trim();
      return rest ? '\u3014\u5df2\u7701\u7565\u6ce8\u5165\u7684\u5386\u53f2\u8bb0\u5fc6\u3015\n\n' + rest : '\u3014\u5df2\u7701\u7565\u6ce8\u5165\u7684\u5386\u53f2\u8bb0\u5fc6\u3015';
    }
    const body = t.split('\n').filter(l => !l.startsWith('[') && !l.startsWith('\u3014') && !/^\s*$/.test(l));
    return '\u3014\u5df2\u7701\u7565\u6ce8\u5165\u7684\u5386\u53f2\u8bb0\u5fc6\u3015\n\n' + body.join('\n').trim();
  }
  return t;
}
const SUB_REPORT_RE = /(\u5b50\u4ee3\u7406|subagent)/i;

function loadSession(dirName) {
  const f = path.join(ROOT, dirName, 'session.v4.jsonl.zstd');
  if (!fs.existsSync(f)) return { error: 'no session.v4.jsonl.zstd' };
  const raw = fs.readFileSync(f);
  const { data, frames, fails } = decompressMulti(raw);
  const evs = [];
  let bad = 0;
  for (const line of data.toString('utf8').split('\n')) {
    if (!line.trim()) continue;
    try { evs.push(JSON.parse(line)); } catch (e) { bad++; }
  }
  return { evs, frames, fails, bad, bytes: raw.length };
}

// ---------- main ----------
fs.mkdirSync(path.join(OUT, 'agents'), { recursive: true });
fs.mkdirSync(path.join(OUT, 'raw'), { recursive: true });

const dirs = fs.readdirSync(ROOT, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name);
const sessions = new Map();
const failures = [];
for (const d of dirs) {
  const r = loadSession(d);
  if (r.error) { failures.push(d + ': ' + r.error); continue; }
  if (r.bad) failures.push(d + ': ' + r.bad + ' \u884c JSON \u89e3\u6790\u5931\u8d25');
  if (r.fails.length) failures.push(d + ': ' + r.fails.length + ' \u4e2a zstd \u5e27\u89e3\u538b\u5931\u8d25');
  const head = r.evs.find(e => e.type === 'session');
  const createdAt = head ? head.createdAt : 0;
  const firstTime = r.evs[0] ? r.evs[0].time || r.evs[0].createdAt || 0 : 0;
  if (createdAt < CUTOFF && firstTime < CUTOFF) continue;
  sessions.set(d, {
    dir: d,
    id: head ? head.id : d,
    evs: r.evs,
    createdAt,
    depth: head ? head.delegationDepth : 0,
    preset: head ? head.agentPreset : '',
  });
}
console.log('dirs', dirs.length, 'keptSessions', sessions.size, 'failures', failures.length);

// catalog mapping: childId -> {name,label,parent}
const nameByChild = new Map();
for (const [, s] of sessions) {
  for (const e of s.evs) {
    if (e.type !== 'subagent/catalog') continue;
    const d = e.data || {};
    if (!d.childId) continue;
    if (!nameByChild.has(d.childId)) nameByChild.set(d.childId, { name: d.name || '', label: d.label || '', parent: s.id, createdAt: d.childCreatedAt || 0 });
  }
}
// also scan non-kept sessions for catalogs (children may start before cutoff safely) -- already covered

// ---------- normalize events ----------
function normalize(evs) {
  const kept = [];
  const dropped = {};
  for (const e of evs) {
    if (!KEEP.has(e.type)) { dropped[e.type] = (dropped[e.type] || 0) + 1; continue; }
    kept.push({ type: e.type, seq: e.seq, time: e.time, data: scrubDeep(e.data) });
  }
  return { kept, dropped };
}

function firstUserLine(evs) {
  for (const e of evs) {
    if (e.type !== 'user/message') continue;
    const t = partsText(e.data && e.data.content);
    const r = renderUserText(t);
    if (r && !SYS_RE.test(t.trim())) return oneLine(r).slice(0, 40);
  }
  return '';
}

// ---------- render ----------
function render(rec, meta) {
  const L = [];
  L.push('# ' + meta.title);
  L.push('');
  L.push('> \u4f1a\u8bdd id\uff1a`' + rec.id + '`  \u00b7  \u4e8b\u4ef6 ' + rec.evs.length + ' \u6761  \u00b7  ' + meta.turnCount + ' \u4e2a\u56de\u5408  \u00b7  \u5c42\u7ea7\uff1a' + meta.rel);
  L.push('>');
  L.push('> \u539f\u59cb JSONL\uff1a`raw/' + rec.id + '.jsonl`');
  L.push('');
  let turn = 0;
  let anyTurn = false;
  for (const e of rec.kept) {
    const d = e.data || {};
    if (e.type === 'turn/start') {
      turn = d.turn || turn + 1;
      anyTurn = true;
      L.push('## \u56de\u5408 ' + turn);
      L.push('');
      continue;
    }
    if (e.type === 'turn/end') { L.push(''); continue; }
    if (e.type === 'subagent/catalog') {
      L.push('\u25b8 \u6d3e\u51fa\u5b50\u4ee3\u7406 `' + (d.name || '\u672a\u547d\u540d') + '`\uff08' + (d.label || '') + '\uff09\u2192 `session-' + (d.childId || '?') + '`');
      L.push('');
      continue;
    }
    if (e.type === 'user/message') {
      let t = partsText(d.content || d.message && d.message.content);
      if (!t) continue;
      t = renderUserText(t);
      if (t === null) continue;
      const isReport = SUB_REPORT_RE.test(t) && /(\u5df2\u5b8c\u6210|\u5b8c\u6210\u901a\u77e5|\u4efb\u52a1\u5b8c\u6210|\u6c47\u62a5|\u62a5\u544a)/.test(t);
      if (isReport) {
        const m = t.match(/\u5b50\u4ee3\u7406\s*[\u300c"`]([^\u300d"`\n]{1,40})[\u300d"`]/) || t.match(/`([a-z0-9-]{2,40})`/);
        L.push('### \u5b50\u4ee3\u7406\u56de\u62a5 \u00b7 ' + (m ? m[1] : '\u672a\u77e5'));
      } else {
        L.push('### \u7528\u6237');
      }
      L.push('');
      L.push(blockquote(t));
      L.push('');
      continue;
    }
    if (e.type === 'assistant/message') {
      const t = partsText(d.message && d.message.content || d.content);
      if (!t) continue;
      L.push('### \u8c03\u5ea6\u53f0');
      L.push('');
      L.push(blockquote(t));
      L.push('');
      continue;
    }
    if (e.type === 'tool/call') {
      L.push('\ud83d\udd27 `' + (d.name || '?') + '` ' + argsSummary(d.arguments));
      L.push('');
      continue;
    }
    if (e.type === 'tool/result') {
      const msg = d.message || {};
      let t = partsText(msg.content || d.content);
      const isErr = !!(msg.isError || d.isError);
      if (!t) { L.push('>\uff08\u7a7a\u7ed3\u679c\uff09'); L.push(''); continue; }
      L.push(isErr ? '> \u274c \u9519\u8bef\u7ed3\u679c' : '> \ud83d\udcc4 \u5de5\u5177\u7ed3\u679c');
      L.push('>');
      L.push(blockquote(trunc(t, 1200)));
      L.push('');
      continue;
    }
  }
  if (!anyTurn) { /* nothing */ }
  return L.join('\n') + '\n';
}

// ---------- lineage ----------
const childrenOf = new Map();
for (const [childId, info] of nameByChild) {
  const p = info.parent;
  if (!childrenOf.has(p)) childrenOf.set(p, []);
  childrenOf.get(p).push({ childId, ...info });
}
const mainRec = sessions.get(MAIN);
if (!mainRec) { console.error('MAIN MISSING'); process.exit(1); }

const records = new Map();
for (const [dir, s] of sessions) records.set(s.id, s);

const order = [];
const visited = new Set();
function walk(sid, depth) {
  if (visited.has(sid)) return;
  visited.add(sid);
  order.push({ sid, depth });
