      return rest ? '\u3014\u5df2\u7701\u7565\u6ce8\u5165\u7684\u5386\u53f2\u8bb0\u5fc6\u3015\n\n' + rest : '\u3014\u5df2\u7701\u7565\u6ce8\u5165\u7684\u5386\u53f2\u8bb0\u5fc6\u3015';
    }
    const body = t.split('\n').filter(l => !l.startsWith('[') && !l.startsWith('\u3014') && !/^\s*$/.test(l));
    return '\u3014\u5df2\u7701\u7565\u6ce8\u5165\u7684\u5386\u53f2\u8bb0\u5fc6\u3015\n\n' + body.join('\n').trim();
