function loadSession(dirName) {
  const f = path.join(ROOT, dirName, 'session.v4.jsonl.zstd');
  if (!fs.existsSync(f)) return { error: 'no session.v4.jsonl.zstd' };
  const raw = fs.readFileSync(f);
  const { data, frames, fails } = decompressMulti(raw);
  const evs = [];
  let bad = 0;
  for (const line of data.toString('utf8').split('\n')) {
    if (!line.trim()) continue;
    try { evs.push(JSON.parse(line)); } catch (e) { bad++; }
  }
  return { evs, frames, fails, bad, bytes: raw.length };
}

