const outs = [];
let i = 0;
while (i < pos.length) {
  let ok = false;
  for (let j = i + 1; j <= pos.length; j++) {
    try { outs.push(zlib.zstdDecompressSync(buf.subarray(pos[i], j < pos.length ? pos[j] : buf.length))); i = j; ok = true; break; } catch (e) { }
  }
  if (!ok) i++;
}
const evs = Buffer.concat(outs).toString('utf8').split('\n').filter(Boolean).map(l => JSON.parse(l));
const cats = evs.filter(e => e.type === 'subagent/catalog');
console.log('CATS', cats.length, JSON.stringify(cats.slice(0, 2).map(c => c.data)));
