const desc = evs.filter(e => e.type === 'subagent/descriptor');
if (desc.length) console.log('DESCRIPTOR', JSON.stringify(desc[0]).slice(0, 500));
console.log('DIRS_NONSTANDARD', JSON.stringify(dirs.filter(d => !/^session-[0-9a-f-]{36}$/.test(d)).slice(0, 6)));

// keyword residue
const KEYS = ['用户', '账号标识', './'];
for (const k of KEYS) {
  let shown = 0;
  const walk = (dir) => {
    for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
