      shown++;
    }
  }
}
walk(OUT);

const buf = fs.readFileSync(path.join(ROOT, MAIN, 'session.v4.jsonl.zstd'));
const pos = [];
for (let i = 0; i <= buf.length - 4; i++) if (buf[i] === 0x28 && buf[i + 1] === 0xb5 && buf[i + 2] === 0x2f && buf[i + 3] === 0xfd) pos.push(i);
const outs = [];
let i = 0;
while (i < pos.length) {
  let ok = false;
  for (let j = i + 1; j <= pos.length; j++) {
    try { outs.push(zlib.zstdDecompressSync(buf.subarray(pos[i], pos[j] === undefined ? buf.length : pos[j]))); i = j; ok = true; break; } catch (e) { }
  }
  if (!ok) i++;
}
const evs = Buffer.concat(outs).toString('utf8').split('\n').filter(Boolean).map(l => JSON.parse(l));
function txt(c) {
  if (typeof c === 'string') return c;
  if (!Array.isArray(c)) return '';
  return c.filter(p => p && p.type === 'text').map(p => p.text).join('\n');
}
let n = 0;
for (const e of evs) {
  if (e.type !== 'user/message') continue;
  const s = txt(e.data && e.data.content).trim();
  if (!s || s.startsWith('<system-reminder>')) continue;
  if (!/(完成|\u56de\u62a5|子代理)/.test(s.slice(0, 300))) continue;
  console.log('UMSG', JSON.stringify(s.slice(0, 150)));
  if (++n >= 8) break;
}
console.log('userMsgWithReportWordsShown', n);
