  for (const p of [['账号标识', '账号标识'], ['./', './'], ['./', './'], ['./', './'], ['./', './'], ['用户', '用户'], ['凭据=', '凭据='], ['凭据', '凭据']]) t = t.split(p[0]).join(p[1]);`;
rep('hard-literal', s => s.replace('\n  return t;\n}\nfunction scrubDeep', HARD + '\n  return t;\n}\nfunction scrubDeep'));

const ISREP_NEW = String.raw`const isReport = /^Background\s+subagent\s+\S+/i.test(t.trim());
      const reportName = ((t.trim().match(/^Background\s+subagent\s+(\S+)/i) || [])[1] || '未知');`;
rep('isreport', s => s.replace(/const isReport = [^\n]*/, () => ISREP_NEW));

const REP_OLD = String.raw`(m ? m[1] : '\u672a\u77e5')`;
rep('report-name', s => s.replace(REP_OLD, () => 'reportName'));

const UOLD = String.raw`L.push('### \u7528\u6237');`;
const UNEW = String.raw`L.push(/^(任务清单更新提醒|对话里的「任务」面板)/.test(t.trim()) ? '### 系统提醒' : '### 用户');`;
rep('sys-nudge-label', s => s.replace(UOLD, () => UNEW));

const ANCHOR = "fs.writeFileSync(path.join(OUT, 'README.md'), readme, 'utf8');";
const EXTRA = "\n\n\u8865\u5145\u8bf4\u660e\uff1a\u4e3b\u4f1a\u8bdd\u91cc\u9664\u4e86\u7528\u6237\u539f\u8bdd\uff0c\u8fd8\u6709\u4e24\u7c7b\u7531\u8fd0\u884c\u65f6\u6ce8\u5165\u7684\u6d88\u606f\u3002\u4e00\u7c7b\u662f\u7cfb\u7edf\u63d0\u9192\uff08\u4f8b\u5982\u5de5\u5177\u8c03\u7528\u540e\u63d0\u9192\u66f4\u65b0\u4efb\u52a1\u6e05\u5355\uff09\uff0c\u6d41\u6c34\u91cc\u6807\u6ce8\u4e3a\u300c\u7cfb\u7edf\u63d0\u9192\u300d\uff0c\u4e0d\u7b97\u7528\u6237\u8bf4\u7684\u8bdd\uff1b\u4e00\u7c7b\u662f\u5b50\u4ee3\u7406\u5b8c\u6210\u901a\u77e5\uff08\u539f\u6587\u4ee5 Background subagent \u2026 finished \u5f00\u5934\u7684\u82f1\u6587\uff09\uff0c\u6807\u6ce8\u4e3a\u300c\u5b50\u4ee3\u7406\u56de\u62a5 \u00b7 \u540d\u5b57\u300d\u5e76\u5b8c\u6574\u4fdd\u7559\uff0c\u90a3\u662f\u5404\u8def\u6210\u679c\u7684\u6c47\u5165\u53e3\u3002\n";
rep('readme-extra', s => s.replace(ANCHOR, () => ANCHOR + "\nfs.appendFileSync(path.join(OUT, 'README.md'), " + JSON.stringify(EXTRA) + ", 'utf8');"));

fs.writeFileSync(F, t, 'utf8');
console.log(log.join('\n'));
