content.arguments:
{"command":"$p='./'; $t=[IO.File]::ReadAllText($p,[Text.Encoding]::UTF8); $old='    kept.push({ type: e.type, seq: e.seq, time: e.time, data: scrubDeep(e.data) });'
$new=@'
    let dd = scrubDeep(e.data);
    if (e.type === 'assistant/message' && dd && dd.message && Array.isArray(dd.message.content)) dd.message.content = dd.message.content.filter(p => !(p && p.type === 'reasoning'));
    if (e.type === 'tool/result' && dd && dd.message && Array.isArray(dd.message.content)) dd.message.content = dd.message.content.map(p => (p && p.type === 'text') ? Object.assign({}, p, { text: trunc(p.text, 1200) }) : p);
    kept.push({ type: e.type, seq: e.seq, time: e.time, data: dd });
'@
$t2=$t.Replace($old,$new); if($t2 -eq $t){Write-Host 'PATCH-MISS'}else{Write-Host 'PATCH-OK'}; [IO.File]::WriteAllText($p,$t2,(New-Object Text.UTF8Encoding($false)))
$d='./'; Get-ChildItem "$d\agents" -File | Remove-Item -Force; Get-ChildItem "$d\raw" -File | Remove-Item -Force
Write-Host '=== export ==='; node ./ 2>&1 | Select-Object -Last 5
$md=(Get-ChildItem "$d\main.md").Length; $ag=(Get-ChildItem "$d\agents" -File | Measure-Object Length -Sum).Sum; $raw=(Get-ChildItem "$d\raw" -File | Measure-Object Length -Sum).Sum
"main.md=$md agentsSum=$ag agentsCount=$((Get-ChildItem "$d\agents" -File).Count) rawSum=$raw rawCount=$((Get-ChildItem "$d\raw" -File).Count)"
"totalDir=" + ((Get-ChildItem $d -Recurse -File | Measure-Object Length -Sum).Sum)
Write-Host '=== biggest raw ==='; Get-ChildItem "$d\raw" -File | Sort-Object Length -Desc | Select-Object -First 3 Name,Length
Write-Host '=== reports ==='; (Select-String -Path "$d\main.md" -Pattern '^### 子代理回报' | Measure-Object).Count
Write-Host '=== sample ==='; Select-String -Path "$d\main.md" -Pattern '^### 子代理回报' | Select-Object -First 2 -ExpandProperty Line; (Get-Content "$d\README.md" -TotalCount 4)","description":"Strip reasoning from raw and rerun export"}

